import { useEffect, useId, useMemo, useState, type ReactNode } from 'react'
import type { PluginInventorySnapshot } from '@deepseek-ai/dsh-api-remotes/client'
import {
  IconChevronDownOutline14,
  IconSearchOutline16,
} from '@deepseek-ai/dsh-client-ui-primitives'
import type { InjectFace, PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type { PluginInventoryLocaleKey } from './locales.ts'
import {
  classifyModule, PLUGIN_GROUP_LABEL_KEY, PLUGIN_GROUP_ORDER,
  type PluginGroupKey,
} from './plugin-groups.ts'
import css from './GroupedInventoryTab.module.css'

/** Registration-side Remote face used by the section. */
export interface GroupedInventoryTabInjected {
  /** Read a current Host inventory snapshot. */
  list: () => Promise<PluginInventorySnapshot>
}

type PluginInventoryEntry = PluginInventorySnapshot['entries'][number]
type PluginFiberPhase = PluginInventoryEntry['fiberPhase']

/** Full component props assembled by the Settings slot renderer. */
export type GroupedInventoryTabProps =
  PropsRuntime<'settings.plugins.tab'>
  & PropsLocale<'settings.pluginManager'>
  & InjectFace<GroupedInventoryTabInjected>

type ViewState =
  | { readonly status: 'loading' }
  | { readonly status: 'error' }
  | { readonly status: 'ready'; readonly snapshot: PluginInventorySnapshot }

/** One non-empty group of the current filtered catalog, in display order. */
interface PluginGroup {
  readonly key: PluginGroupKey
  readonly entries: readonly PluginInventoryEntry[]
}

const PHASE_KEYS = {
  pending: 'pending',
  loading: 'loadingPhase',
  active: 'active',
  failed: 'failed',
  unloading: 'unloading',
} satisfies Record<Exclude<PluginFiberPhase, null>, PluginInventoryLocaleKey>

/** Localized accessible label for one root Fiber phase. */
function phaseLabel(
  phase: PluginFiberPhase,
  t: GroupedInventoryTabProps['t'],
): string {
  return phase === null ? t('unobserved') : t(PHASE_KEYS[phase])
}

/** Compact a module specifier without guessing whether its Loader id was generated. */
function moduleShortName(moduleName: string): string {
  const unscoped = moduleName.startsWith('@') ? moduleName.slice(moduleName.indexOf('/') + 1) : moduleName
  return unscoped
    .replace(/^cordis:/, '')
    .replace(/^cordis-plugin-/, '')
    .replace(/^dsh-(?:host-|client-)?/, '')
}

/** Whether an inventory row matches the local catalog query. */
function matches(entry: PluginInventoryEntry, normalizedQuery: string): boolean {
  if (normalizedQuery.length === 0) return true
  return [entry.moduleName, entry.entryId]
    .some(value => value.toLocaleLowerCase().includes(normalizedQuery))
}

/** Group a filtered entry list in display order, skipping empty groups. */
function groupEntries(entries: readonly PluginInventoryEntry[]): readonly PluginGroup[] {
  const byGroup = new Map<PluginGroupKey, PluginInventoryEntry[]>()
  for (const entry of entries) {
    const key = classifyModule(entry.moduleName)
    const bucket = byGroup.get(key)
    if (bucket === undefined) {
      byGroup.set(key, [entry])
    } else {
      bucket.push(entry)
    }
  }
  return PLUGIN_GROUP_ORDER.flatMap((key) => {
    const group = byGroup.get(key)
    return group === undefined ? [] : [{ key, entries: group }]
  })
}

/** Render the grouped, searchable current Loader inventory. */
export function GroupedInventoryTab({ list, t }: GroupedInventoryTabProps): ReactNode {
  const catalogId = useId()
  const [request, setRequest] = useState(0)
  const [query, setQuery] = useState('')
  const [expanded, setExpanded] = useState<PluginInventoryEntry['entryId'] | null>(null)
  const [collapsedGroups, setCollapsedGroups] = useState<ReadonlySet<PluginGroupKey>>(() => new Set())
  const [state, setState] = useState<ViewState>({ status: 'loading' })

  useEffect(() => {
    let current = true
    void Promise.resolve().then(() => list()).then(
      (snapshot) => { if (current) setState({ status: 'ready', snapshot }) },
      () => { if (current) setState({ status: 'error' }) },
    )
    return () => { current = false }
  }, [list, request])

  const normalizedQuery = query.trim().toLocaleLowerCase()
  const filteredEntries = useMemo(
    () => state.status === 'ready'
      ? state.snapshot.entries.filter(entry => matches(entry, normalizedQuery))
      : [],
    [normalizedQuery, state],
  )
  const groups = useMemo(() => groupEntries(filteredEntries), [filteredEntries])

  useEffect(() => {
    if (expanded !== null && !filteredEntries.some(entry => entry.entryId === expanded)) {
      setExpanded(null)
    }
  }, [expanded, filteredEntries])

  const retry = (): void => {
    setState({ status: 'loading' })
    setRequest(value => value + 1)
  }

  const toggleGroup = (key: PluginGroupKey): void => {
    setCollapsedGroups((previous) => {
      const next = new Set(previous)
      if (next.has(key)) {
        next.delete(key)
      } else {
        next.add(key)
      }
      return next
    })
  }

  const expandAll = (): void => { setCollapsedGroups(new Set()) }
  const collapseAll = (): void => {
    setCollapsedGroups(new Set(groups.map(group => group.key)))
  }

  return (
    <div className={css.section} aria-busy={state.status === 'loading'}>
      {state.status === 'loading' ? <p className={css.status}>{t('loading')}</p> : null}
      {state.status === 'error' ? (
        <div className={css.failure}>
          <p role="alert">{t('error')}</p>
          <button type="button" onClick={retry}>{t('retry')}</button>
        </div>
      ) : null}
      {state.status === 'ready' ? (
        <div className={css.catalog}>
          <label className={css.search}>
            <IconSearchOutline16 aria-hidden="true" />
            <span className={css.visuallyHidden}>{t('search')}</span>
            <input
              type="search"
              value={query}
              placeholder={t('search')}
              aria-label={t('search')}
              onChange={(event) => { setQuery(event.currentTarget.value) }}
            />
          </label>
          <div className={css.catalogHeading}>
            <h3>{t('catalog')}</h3>
            <span data-plugin-count={filteredEntries.length}>{filteredEntries.length}</span>
            {groups.length > 1 ? (
              <span className={css.groupControls}>
                <button type="button" onClick={expandAll}>{t('expandAll')}</button>
                <button type="button" onClick={collapseAll}>{t('collapseAll')}</button>
              </span>
            ) : null}
          </div>
          {state.snapshot.entries.length === 0 ? <p className={css.status}>{t('empty')}</p> : null}
          {state.snapshot.entries.length > 0 && filteredEntries.length === 0
            ? <p className={css.status}>{t('emptySearch')}</p>
            : null}
          {groups.length > 0 ? (
            <div className={css.groups}>
              {groups.map((group) => {
                const collapsed = collapsedGroups.has(group.key)
                const groupLabel = t(PLUGIN_GROUP_LABEL_KEY[group.key])
                return (
                  <section
                    className={css.group}
                    key={group.key}
                    data-group={group.key}
                    data-collapsed={collapsed ? 'true' : undefined}
                  >
                    <button
                      className={css.groupToggle}
                      type="button"
                      aria-expanded={!collapsed}
                      aria-label={groupLabel}
                      onClick={() => { toggleGroup(group.key) }}
                    >
                      <IconChevronDownOutline14 className={css.groupChevron} size={12} aria-hidden="true" />
                      <span className={css.groupName}>{groupLabel}</span>
                      <span className={css.groupCount} data-group-count={group.key}>{group.entries.length}</span>
                    </button>
                    {collapsed ? null : (
                      <ul className={css.cards}>
                        {group.entries.map((entry) => {
                          const status = phaseLabel(entry.fiberPhase, t)
                          const title = moduleShortName(entry.moduleName)
                          const configuration = t(entry.enabled ? 'enabledTag' : 'disabledTag')
                          const open = expanded === entry.entryId
                          const detailId = `${catalogId}-details-${encodeURIComponent(entry.entryId)}`
                          return (
                            <li
                              className={css.card}
                              key={entry.entryId}
                              data-plugin-entry={entry.entryId}
                              data-open={open ? 'true' : undefined}
                            >
                              <button
                                className={css.cardContent}
                                type="button"
                                aria-expanded={open}
                                aria-controls={detailId}
                                aria-label={entry.enabled ? `${title}, ${status}, ${configuration}` : `${title}, ${configuration}`}
                                onClick={() => {
                                  setExpanded(current => current === entry.entryId ? null : entry.entryId)
                                }}
                              >
                                <strong className={css.cardTitle} title={entry.moduleName}>{title}</strong>
                                <span className={css.cardTrailing}>
                                  {entry.enabled ? (
                                    <span
                                      className={css.statusDot}
                                      data-phase={entry.fiberPhase ?? 'unobserved'}
                                      role="img"
                                      aria-label={status}
                                      title={status}
                                    />
                                  ) : null}
                                  <span className={css.configTag} data-enabled={entry.enabled ? 'true' : 'false'}>
                                    {configuration}
                                  </span>
                                  <IconChevronDownOutline14 className={css.chevron} size={12} aria-hidden="true" />
                                </span>
                              </button>
                              {open ? (
                                <div className={css.cardDetails} id={detailId}>
                                  <code className={css.entryValue} data-loader-entry>{entry.entryId}</code>
                                  <dl className={css.details}>
                                    <div>
                                      <dt>{t('configuration')}</dt>
                                      <dd>{configuration}</dd>
                                    </div>
                                    {entry.enabled ? (
                                      <div>
                                        <dt>{t('cordis')}</dt>
                                        <dd>{status}</dd>
                                      </div>
                                    ) : null}
                                  </dl>
                                </div>
                              ) : null}
                            </li>
                          )
                        })}
                      </ul>
                    )}
                  </section>
                )
              })}
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}